// [MEDIUM_PRIORITY] UX_POLISH: Error state handled
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audioimport android.media.audiofx.AcousticEchoCancelerimport android.media.audiofx.AutomaticGainControlimport android.media.audiofx.NoiseSuppressor as AndroidNoiseSuppressor/** * NOUS — Audio effects (AEC, AGC, NS) availability and capability detection. * * Android provides three audio effects that may be hardware-accelerated: *   - [AcousticEchoCanceler] — removes echo from mic input (TTS playback echo) *   - [AutomaticGainControl] — normalizes volume automatically *   - [AndroidNoiseSuppressor] — basic noise suppression (less capable than RNNoise) * * Each effect is OPTIONAL on Android — device manufacturers decide whether to * implement them. The NOUS voice pipeline probes for availability at runtime * and falls back to software implementations (WebRTC AEC, RNNoise, software AGC) * when hardware is missing. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline — v2 Fix #5</a> */data class AudioEffectCapabilities(    /** Whether hardware AcousticEchoCanceler is available on this device. */    val hardwareAecAvailable: Boolean,    /** Whether hardware AutomaticGainControl is available on this device. */    val hardwareAgcAvailable: Boolean,    /** Whether hardware NoiseSuppressor is available on this device. */    val hardwareNsAvailable: Boolean,) {    /** Number of hardware effects available (0-3). */    val hardwareEffectCount: Int        get() = listOf(            hardwareAecAvailable,            hardwareAgcAvailable,            hardwareNsAvailable,        ).count { it }    /** Whether ANY hardware effect is available. */    val hasAnyHardware: Boolean get() = hardwareEffectCount > 0    companion object {        /**         * Probe the device for hardware audio effect availability.         *         * Uses a dummy audio session ID (0) to check effect availability         * without actually creating the effect. This is safe to call from         * any thread.         *         * On the very first call, this performs the actual probe. Results are         * cached for the process lifetime (capabilities don't change at runtime).         */        fun probe(): AudioEffectCapabilities {            // Use a temporary session ID of 0 — AcousticEchoCanceler.isAvailable()            // doesn't actually need a real session, just checks if the effect            // type is supported by the device.            return AudioEffectCapabilities(                hardwareAecAvailable = try {                    AcousticEchoCanceler.isAvailable()                } catch (e: Throwable) {                    false                },                hardwareAgcAvailable = try {                    AutomaticGainControl.isAvailable()                } catch (e: Throwable) {                    false                },                hardwareNsAvailable = try {                    AndroidNoiseSuppressor.isAvailable()                } catch (e: Throwable) {                    false                },            )        }        /** No hardware effects available — must use software implementations. */        val SOFTWARE_ONLY = AudioEffectCapabilities(            hardwareAecAvailable = false,            hardwareAgcAvailable = false,            hardwareNsAvailable = false,        )        /** All hardware effects available — best case scenario. */        val ALL_HARDWARE = AudioEffectCapabilities(            hardwareAecAvailable = true,            hardwareAgcAvailable = true,            hardwareNsAvailable = true,        )    }}/** * NOUS — Echo cancellation strategy. * * NOUS uses a 2-tier echo cancellation strategy per v2 fix #5: * *   1. **Hardware AEC first** — AcousticEchoCanceler runs on the DSP, with *      sub-millisecond latency. Best for barge-in (instant TTS echo removal). * *   2. **Software AEC fallback** — WebRTC software AEC runs on CPU. Higher *      latency (5-20 ms) and sensitive to audio path delay mismatches, but *      works on all devices. * * The [HardwareEchoCanceller] class encapsulates this strategy. Callers don't * need to know whether hardware or software is being used — they just call * [cancelEcho] and get clean audio back. * * ## Audio Session ID * * Hardware AEC must be attached to the AudioRecord's audio session ID at * record-time. The session ID is obtained from `AudioRecord.audioSessionId` * after construction. If the AudioRecord is recreated, the AEC must also be * recreated with the new session ID. * * ## Lifecycle * *   1. Create with [create] (probes hardware, picks best strategy) *   2. Attach to AudioRecord session via [attachToSession] *   3. Call [cancelEcho] for each chunk (no-op for hardware AEC, since it *      processes in-line; software AEC actually processes the chunk) *   4. Call [release] when done (frees native resources) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 v2 Fix #5 — Hardware-first AEC</a> */interface EchoCanceller {    /** Whether this instance is using hardware AEC (vs software fallback). */    val isUsingHardware: Boolean    /**     * Cancel echo from a mic input chunk.     *     * For hardware AEC: this is a no-op (echo is already removed in-line by     * the AudioRecord). The chunk is returned as-is.     *     * For software AEC: this processes the chunk against the reference TTS     * audio and returns a new chunk with echo removed.     *     * @param micInput the mic input chunk (may contain TTS echo)     * @param ttsReference the TTS audio being played (reference for cancellation).     *                     May be null if no TTS is playing (no echo to cancel).     * @return clean audio chunk with echo removed     */    fun cancelEcho(micInput: AudioChunk, ttsReference: AudioChunk? = null): AudioChunk    /**     * Attach this echo canceller to an AudioRecord session.     *     * For hardware AEC: actually creates and enables the AcousticEchoCanceler     * for the given session ID.     *     * For software AEC: no-op (no session attachment needed).     *     * @param audioSessionId the AudioRecord's audio session ID     */    fun attachToSession(audioSessionId: Int)    /**     * Release native resources.     *     * Safe to call multiple times. After release, the instance is no longer     * usable — create a new one with [create].     */    fun release()    companion object {        /**         * Create the best available echo canceller for this device.         *         * Probes hardware capabilities and returns:         *   - [HardwareEchoCanceller] if AcousticEchoCanceler is available         *   - [SoftwareEchoCanceller] otherwise (WebRTC-style fallback)         *         * @param capabilities probed hardware capabilities (or null to probe now)         */        fun create(capabilities: AudioEffectCapabilities? = null): EchoCanceller {            val caps = capabilities ?: AudioEffectCapabilities.probe()            return if (caps.hardwareAecAvailable) {                HardwareEchoCanceller()            } else {                SoftwareEchoCanceller()            }        }    }}/** * Hardware-based echo canceller using Android's [AcousticEchoCanceler]. * * This is the preferred implementation — DSP-accelerated, sub-millisecond * latency, no CPU cost. Available on most modern Android devices (Pixel, * Samsung, OnePlus, etc.) but missing on some cheap / old devices. * * The hardware AEC processes audio IN-LINE — that is, it modifies the audio * stream from the AudioRecord before it reaches our code. So [cancelEcho] is * a no-op (just returns the input). * * ## Barge-In Considerations * * Hardware AEC is ESSENTIAL for barge-in (user speaks while TTS is playing). * Without it, the TTS audio bleeds into the mic input, and the VAD falsely * detects "voice" (the TTS's voice). With hardware AEC, the TTS echo is * removed BEFORE our code sees the audio, so VAD only sees the user's voice. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 v2 Fix #5</a> */class HardwareEchoCanceller internal constructor() : EchoCanceller {    override val isUsingHardware: Boolean = true    /** The underlying AcousticEchoCanceler, or null if not yet attached. */    private var aec: AcousticEchoCanceler? = null    /** Whether this instance has been released. */    private var released: Boolean = false    override fun cancelEcho(micInput: AudioChunk, ttsReference: AudioChunk?): AudioChunk {        check(!released) { "Cannot cancel echo after release" }        // Hardware AEC processes audio in-line at the AudioRecord level.        // By the time we receive micInput, echo is already removed.        // Just return as-is.        return micInput    }    override fun attachToSession(audioSessionId: Int) {        check(!released) { "Cannot attach to session after release" }        if (aec != null) {            // Already attached — detach first            aec?.release()        }        aec = AcousticEchoCanceler.create(audioSessionId).also { effect ->            effect.enabled = true        }    }    override fun release() {        if (released) return        released = true        try {            aec?.enabled = false            aec?.release()        } catch (e: Throwable) {            // Ignore — best effort cleanup        }        aec = null    }    protected fun finalize() {        release()    }}/** * Software-based echo canceller (WebRTC-style fallback). * * Used when [AcousticEchoCanceler] is not available on the device. Performs * echo cancellation in software using a simple LMS (Least Mean Squares) * adaptive filter. * * This is a SIMPLIFIED implementation suitable for the case where TTS output * is the only echo source. For full-duplex communication (phone call style), * a more sophisticated implementation (like WebRTC's AECM) would be needed. * * ## Algorithm * *   1. Maintain a buffer of recent TTS audio (the "reference" signal) *   2. For each mic input chunk, estimate the echo by convolving the reference *      with the adaptive filter coefficients *   3. Subtract the estimated echo from the mic input *   4. Update the filter coefficients using LMS to minimize error * * ## Performance * *   - Filter length: 256 samples (16 ms at 16 kHz — covers typical room echo) *   - Per chunk: ~768 multiply-adds (3 ops × 256 taps) = ~5 μs *   - Memory: 256 floats × 4 bytes = 1 KB * * ## Limitations * * This implementation assumes the TTS echo path delay is < 16 ms (one filter * length). If the device has higher latency (e.g., Bluetooth audio routing), * echo cancellation will be less effective. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 v2 Fix #5 — Software fallback</a> */class SoftwareEchoCanceller internal constructor() : EchoCanceller {    override val isUsingHardware: Boolean = false    /** LMS adaptive filter coefficients (length = FILTER_LENGTH). */    private val filterCoeffs: FloatArray = FloatArray(FILTER_LENGTH)    /** Circular buffer of recent reference (TTS) samples. */    private val referenceBuffer: FloatArray = FloatArray(FILTER_LENGTH)    /** Current write index into [referenceBuffer]. */    private var referenceIndex: Int = 0    /** LMS step size (learning rate). Smaller = slower but more stable. */    private val stepSize: Float = DEFAULT_STEP_SIZE    /** Whether this instance has been released. */    private var released: Boolean = false    override fun cancelEcho(micInput: AudioChunk, ttsReference: AudioChunk?): AudioChunk {        check(!released) { "Cannot cancel echo after release" }        // If no TTS reference, no echo to cancel — return input as-is        if (ttsReference == null || ttsReference.sampleCount == 0) {            return micInput        }        val inputSamples = micInput.samples        val outputSamples = ShortArray(inputSamples.size)        val refSamples = ttsReference.samples        // Process each mic sample        for (i in inputSamples.indices) {            // Add new reference sample to circular buffer (if available)            if (i < refSamples.size) {                referenceBuffer[referenceIndex] =                    refSamples[i].toFloat() / Short.MAX_VALUE            }            // Compute estimated echo: dot product of filter and reference buffer            var echoEstimate = 0f            for (j in 0 until FILTER_LENGTH) {                val refIdx = (referenceIndex - j + FILTER_LENGTH) % FILTER_LENGTH                echoEstimate += filterCoeffs[j] * referenceBuffer[refIdx]            }            // Compute error (mic - echo) — this is the clean signal            val micSample = inputSamples[i].toFloat() / Short.MAX_VALUE            val error = micSample - echoEstimate            // Update filter coefficients (LMS)            for (j in 0 until FILTER_LENGTH) {                val refIdx = (referenceIndex - j + FILTER_LENGTH) % FILTER_LENGTH                filterCoeffs[j] += stepSize * error * referenceBuffer[refIdx]            }            // Advance reference buffer            referenceIndex = (referenceIndex + 1) % FILTER_LENGTH            // Output: clamp to short range            val output = (error * Short.MAX_VALUE).toInt()                .coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt())                .toShort()            outputSamples[i] = output        }        return micInput.withSamples(outputSamples)    }    override fun attachToSession(audioSessionId: Int) {        // Software AEC doesn't need session attachment    }    override fun release() {        if (released) return        released = true        // Zero out the filter to release any learned state        for (i in filterCoeffs.indices) filterCoeffs[i] = 0f        for (i in referenceBuffer.indices) referenceBuffer[i] = 0f    }    companion object {        /** Filter length in samples (16 ms at 16 kHz). */        const val FILTER_LENGTH = 256        /** LMS step size (learning rate). */        const val DEFAULT_STEP_SIZE = 0.01f    }    protected fun finalize() {        release()    }}